#!/usr/bin/env python3
"""R10: engine-level mutants NOT generated by Figram/Mutate.lean (which only mutates machine tables).
Usage: mutants.py list | mutants.py apply NAME <repo-dir>  (exact single-occurrence replacement)."""
import sys
C, E = "Figram/Core.lean", "Figram/Engine.lean"
CURTOK = '''/-- (мутант) жетон берётся из снимка запроса, а не из поля token. -/
def curTok (kvs : Obj) (id : String) (dflt : Nat) : Nat :=
  match get kvs "snapshot" with
  | some (.obj s) =>
    (match get s "timers" with
     | some (.obj ts) =>
       (match get ts id with
        | some (.num m e) => (numToNat m e).getD dflt
        | _ => dflt)
     | _ => dflt)
  | _ => dflt

def decEvent'''
M = {
 # name: (shared-with-oracle?, [(file, old, new)], description)
 "accepts-any-token": ("shared", [(C, "  | .timer id tok => decide (lookup s.timers id = some tok)",
                                     "  | .timer id _ => (lookup s.timers id).isSome")],
    "Snapshot.accepts: таймер принимается с любым жетоном (общий код ядра и эталона)"),
 "engine-token-from-snapshot": ("engine", [(E, "def decEvent", CURTOK),
     (E, "      | some t => pure (.timer (name.drop 6).toString t)",
         "      | some t => pure (.timer (name.drop 6).toString (curTok kvs (name.drop 6).toString t))")],
    "Engine.decEvent: жетон таймера берётся из снимка запроса (устаревший жетон принимается)"),
 "seq-bump-on-ignored": ("core", [(C, "    | none => (s, [])\n    | some r =>",
                                     "    | none => ({ s with seq := s.seq + 1 }, [])\n    | some r =>")],
    "Machine.step: seq растёт и на событии без стрелки"),
 "seq-no-bump": ("shared", [(C, "acts.foldl (realizeOne (s.seq + 1)) ({ s with state := T, seq := s.seq + 1 }, [])",
                               "acts.foldl (realizeOne (s.seq + 1)) ({ s with state := T }, [])")],
    "realize: seq не растёт на переходе (жетоны прежние)"),
 "token-old-seq": ("shared", [(C, "acts.foldl (realizeOne (s.seq + 1))", "acts.foldl (realizeOne s.seq)")],
    "realize: жетон таймера = старый seq вместо нового"),
 "never-need": ("engine", [(E, "(dedup (m.requiredGuards s.state ev.key)).filter fun n => !(gs.any (·.1 == n))",
                              "(dedup (m.requiredGuards s.state ev.key)).filter fun n => !(gs.any (·.1 == n)) && n.isEmpty")],
    "Engine.missing: need не выдаётся никогда, недостающие условия = false"),
 "need-only-if-no-guards": ("engine", [(E, "(dedup (m.requiredGuards s.state ev.key)).filter fun n => !(gs.any (·.1 == n))",
                                          "(dedup (m.requiredGuards s.state ev.key)).filter fun n => gs.isEmpty && n != \"\"")],
    "Engine.missing: при частично переданных условиях недостающие молча = false"),
 "drop-recovered-stepReply": ("engine", [(E, "else pure (result id s' as (decide (s.state ∉ m.states)))",
                                            "else pure (result id s' as false)")],
    "Engine.stepReply: флаг recovered не выставляется"),
 "drop-recovered-result": ("engine", [(E, "    ++ field \"recovered\" recovered (.bool true))",
                                         "    ++ field \"recovered\" (recovered && as.isEmpty) (.bool true))")],
    "Engine.result: recovered печатается только без действий (фактически никогда)"),
 "overflow-ge": ("engine", [(E, "    if s'.seq > maxInt then throw \"seq_overflow\"\n    else pure",
                               "    if s'.seq ≥ maxInt then throw \"seq_overflow\"\n    else pure")],
    "Engine.stepReply: seq_overflow на единицу раньше"),
 "overflow-plus1": ("engine", [(E, "    if s'.seq > maxInt then throw \"seq_overflow\"\n    else pure",
                                  "    if s'.seq > maxInt + 1 then throw \"seq_overflow\"\n    else pure")],
    "Engine.stepReply: seq_overflow на единицу позже (выдаётся seq 2^53)"),
 "restart-overflow-plus1": ("engine", [(E, "    if s'.seq > maxInt then throw \"seq_overflow\"\n    pure (result id s' as false)",
                                          "    if s'.seq > maxInt + 1 then throw \"seq_overflow\"\n    pure (result id s' as false)")],
    "Engine restart: seq_overflow на единицу позже"),
 "restart-keeps-resume": ("engine", [(E, "let (s', as) := m.recover { s with resume := [] }", "let (s', as) := m.recover s")],
    "Engine restart: запомненные места не очищаются"),
 "swap-exit-entry": ("core", [(C, "realize s T (m.exitOf s.state ++ b.actions ++ m.entryOf T)",
                                 "realize s T (m.entryOf T ++ b.actions ++ m.exitOf s.state)")],
    "Machine.fire: вход перед выходом"),
 "recover-no-cancel": ("core", [(C, "realize s m.initial (s.timers.map (fun p => .cancelTimer p.1) ++ m.initActions)",
                                   "realize s m.initial m.initActions")],
    "Machine.recover: таймеры удалённого места не отменяются"),
 "hello-version-2": ("engine", [(E, "def protocolVersion : Nat := 1", "def protocolVersion : Nat := 2")],
    "Engine hello: версия протокола 2"),
 "snapshot-unknown-keys": ("engine", [(E, "  match kvs.find? (fun p => decide (p.1 ∉ snapshotKeys)) with",
                                         "  match kvs.find? (fun p => decide (p.1 ∉ snapshotKeys) && false) with")],
    "Engine.checkKeys: неизвестные поля снимка принимаются"),
 "snapshot-any-version": ("engine", [(E, "if (← boundedNat \"«v»\" j) = 1 then pure ()", "if (← boundedNat \"«v»\" j) ≥ 1 then pure ()")],
    "Engine.checkVersion: принимается v ≥ 1"),
 "guards-lenient": ("engine", [(E, "      | (k, _) => throw s!\"условие «{k}»: ожидалось true или false\"",
                                  "      | (k, _) => pure (k, false)")],
    "Engine.decGuards: не-булево значение условия молча = false"),
 "timer-token-default-0": ("engine", [(E, "    | _ => throw \"для события таймера нужно поле «token»\"",
                                         "    | _ => pure (.timer (name.drop 6).toString 0)")],
    "Engine.decEvent: без token жетон = 0 вместо ошибки"),
}
if __name__ == "__main__":
    if sys.argv[1] == "list":
        for k, (kind, _, d) in M.items(): print(f"{k}\t{kind}\t{d}")
    else:
        name, root = sys.argv[2], sys.argv[3]
        for f, a, b in M[name][1]:
            p = f"{root}/{f}"; s = open(p, encoding="utf-8").read()
            if s.count(a) != 1: sys.exit(f"{name}: {f}: {s.count(a)} вхождений {a!r}")
            open(p, "w", encoding="utf-8").write(s.replace(a, b))
